        ["admin.hero.image.edit"] = ["Show the full image or edit the visible area","Mostrar toda la imagen o editar el área visible","Afficher toute l’image ou modifier la zone visible","Mostra tutta l’immagine o modifica l’area visibile","Mostrar a imagem inteira ou editar a área visível","전체 표시 또는 사용할 영역 편집","全体表示または表示範囲を編集","显示完整图片或编辑可见区域","顯示完整圖片或編輯可見區域","Hiện toàn bộ ảnh hoặc chỉnh vùng hiển thị"],
        ["admin.hero.image.tap"] = ["Select the photo to edit its desktop and phone area","Selecciona la foto para editar el área en PC y móvil","Sélectionnez la photo pour modifier les zones ordinateur et mobile","Seleziona la foto per modificare l’area desktop e mobile","Selecione a foto para editar a área no computador e celular","사진을 눌러 PC·폰 표시 영역 편집","写真を選択してPC・スマホの表示範囲を編集","选择图片以编辑电脑和手机显示区域","選擇圖片以編輯電腦與手機顯示區域","Chọn ảnh để chỉnh vùng hiển thị trên máy tính và điện thoại"],
        ["admin.hero.image.recommend"] = ["Recommended: a 4:5 image with margins and a short edge of at least 2,000 px. Desktop uses 16:9; mobile uses the selected device ratio.","Recomendado: imagen 4:5 con margen y lado corto de al menos 2.000 px. Escritorio usa 16:9 y móvil la proporción del dispositivo.","Recommandé : image 4:5 avec marge et petit côté d’au moins 2 000 px. Le bureau utilise 16:9 et le mobile le format de l’appareil.","Consigliata: immagine 4:5 con margini e lato corto di almeno 2.000 px. Desktop usa 16:9, mobile il rapporto del dispositivo.","Recomendado: imagem 4:5 com margem e lado curto de pelo menos 2.000 px. Desktop usa 16:9 e celular a proporção escolhida.","권장 원본: 짧은 변 2,000px 이상, 여백이 있는 4:5 사진. PC는 16:9, 폰은 선택한 기기 비율로 영역을 지정합니다.","推奨：短辺2,000px以上で余白のある4:5画像。PCは16:9、モバイルは選択端末の比率を使用します。","建议使用短边至少 2,000px、带留白的 4:5 图片。桌面端使用 16:9，移动端使用所选设备比例。","建議使用短邊至少 2,000px、帶留白的 4:5 圖片。桌面端使用 16:9，行動端使用所選裝置比例。","Khuyên dùng ảnh 4:5 có lề, cạnh ngắn ít nhất 2.000px. Máy tính dùng 16:9; điện thoại dùng tỷ lệ thiết bị đã chọn."],
        ["admin.hero.image.edit.area"] = ["Show full image · edit visible area","Mostrar imagen completa · editar área visible","Afficher l’image entière · modifier la zone visible","Mostra immagine intera · modifica area visibile","Mostrar imagem inteira · editar área visível","전체 표시 · 사용할 영역 편집","全体表示・使用範囲を編集","完整显示 · 编辑可用区域","完整顯示・編輯使用區域","Hiện toàn bộ · chỉnh vùng sử dụng"],
        ["admin.hero.crop.phone"] = ["Phone","Teléfono","Téléphone","Telefono","Telefone","폰","スマートフォン","手机","手機","Điện thoại"],
        ["admin.hero.crop.full"] = ["Show full image","Mostrar imagen completa","Afficher l’image entière","Mostra immagine intera","Mostrar imagem inteira","전체 표시","全体表示","完整显示","完整顯示","Hiện toàn bộ"],
        ["admin.hero.crop.area"] = ["Use rectangular area","Usar área rectangular","Utiliser une zone rectangulaire","Usa area rettangolare","Usar área retangular","사각형 영역 사용","矩形範囲を使用","使用矩形区域","使用矩形區域","Dùng vùng hình chữ nhật"],
        ["admin.preview.layout.message"] = ["The {0} layout is shown in the preview. Save settings to publish it.","El diseño {0} aparece en la vista previa. Guarda la configuración para publicarlo.","La mise en page {0} est affichée dans l’aperçu. Enregistrez pour la publier.","Il layout {0} è mostrato nell'anteprima. Salva le impostazioni per pubblicarlo.","O layout {0} aparece na prévia. Salve as configurações para publicar.","{0} 레이아웃을 미리보기에 반영했습니다. 설정을 저장하면 공개 화면에 적용됩니다.","{0}レイアウトをプレビューに反映しました。設定を保存すると公開されます。","已在预览中显示 {0} 布局。保存设置后将发布。","已在預覽中顯示 {0} 版面。儲存設定後將發佈。","Bố cục {0} đã hiển thị trong bản xem trước. Lưu cài đặt để xuất bản."],
        ["admin.preview.theme.message"] = ["The {0} theme is shown in the preview.","El tema {0} aparece en la vista previa.","Le thème {0} est affiché dans l’aperçu.","Il tema {0} è mostrato nell'anteprima.","O tema {0} aparece na prévia.","{0} 테마를 미리보기에 반영했습니다.","{0}テーマをプレビューに反映しました。","已在预览中显示 {0} 主题。","已在預覽中顯示 {0} 主題。","Chủ đề {0} đã hiển thị trong bản xem trước."],
        ["admin.preview.custom.message"] = ["Your custom theme is shown in the preview.","Tu tema personalizado aparece en la vista previa.","Votre thème personnalisé est affiché dans l’aperçu.","Il tuo tema personalizzato è mostrato nell'anteprima.","Seu tema personalizado aparece na prévia.","나만의 테마를 미리보기에 반영했습니다.","カスタムテーマをプレビューに反映しました。","已在预览中显示自定义主题。","已在預覽中顯示自訂主題。","Chủ đề tùy chỉnh đã hiển thị trong bản xem trước."],
        ["admin.preview.palette.message"] = ["A readable palette was generated from the representative color and applied to the preview.","Se generó una paleta legible a partir del color principal y se aplicó a la vista previa.","Une palette lisible a été générée à partir de la couleur principale et appliquée à l’aperçu.","Una palette leggibile è stata generata dal colore principale e applicata all'anteprima.","Uma paleta legível foi gerada da cor principal e aplicada à prévia.","대표 색상으로 읽기 편한 팔레트를 생성해 미리보기에 반영했습니다.","代表色から読みやすいパレットを生成し、プレビューに反映しました。","已根据主色生成易读配色并应用到预览。","已依代表色產生易讀配色並套用至預覽。","Đã tạo bảng màu dễ đọc từ màu đại diện và áp dụng vào bản xem trước."],
        ["admin.preview.color.message"] = ["Color changes are shown in the preview. They are not public until settings are saved.","Los cambios de color aparecen en la vista previa y no serán públicos hasta guardar.","Les changements de couleur sont visibles dans l’aperçu et ne seront publics qu’après enregistrement.","Le modifiche ai colori sono visibili nell'anteprima e non pubbliche finché non salvi.","As mudanças de cor aparecem na prévia e só serão públicas após salvar.","세부 색상 변경을 미리보기에 반영했습니다. 설정 저장 전까지 공개 화면에는 적용되지 않습니다.","色の変更をプレビューに反映しました。設定を保存するまで公開画面には適用されません。","颜色更改已显示在预览中，保存设置前不会公开。","色彩變更已顯示於預覽，儲存設定前不會公開。","Thay đổi màu đã hiển thị trong bản xem trước và chưa công khai cho đến khi lưu."],
        ["admin.hero.crop.title"] = ["Hero image display area","Área visible de la imagen principal","Zone visible de l’image principale","Area visibile dell’immagine principale","Área visível da imagem principal","히어로 이미지 표시 영역","ヒーロー画像の表示範囲","主视觉图片显示区域","主視覺圖片顯示區域","Vùng hiển thị ảnh chính"],
        ["admin.hero.crop.desc"] = ["Use the full photo or draw, move and resize a fixed-ratio rectangle.","Usa toda la foto o dibuja, mueve y cambia el tamaño de un rectángulo fijo.","Utilisez toute la photo ou dessinez, déplacez et redimensionnez un cadre fixe.","Usa tutta la foto o disegna, sposta e ridimensiona un riquadro fisso.","Use a foto inteira ou desenhe, mova e redimensione um retângulo fixo.","전체 사진을 쓰거나, 화면 비율이 고정된 사각형을 그리고 이동·확대해 사용할 영역을 고르세요.","写真全体を使うか、固定比率の枠を描いて移動・拡大し表示範囲を選びます。","使用完整图片，或绘制、移动并缩放固定比例的矩形。","使用完整圖片，或繪製、移動並縮放固定比例的矩形。","Dùng toàn bộ ảnh hoặc vẽ, di chuyển và đổi kích thước khung theo tỷ lệ cố định."],
        ["admin.hero.crop.source"] = ["Best-quality source","Fuente de mejor calidad","Source de meilleure qualité","Originale di massima qualità","Original com melhor qualidade","가장 선명하게 보이는 원본","高画質の元画像","最佳清晰度原图","最佳清晰度原圖","Ảnh gốc rõ nét nhất"],
        ["admin.hero.crop.source.hint"] = ["Short edge 2,000 px or more · 2000×2500 (4:5) recommended · keep people and text away from the edges","Lado corto de 2.000 px o más · se recomienda 2000×2500 (4:5) · deja margen alrededor de personas y texto","Petit côté de 2 000 px minimum · 2000×2500 (4:5) recommandé · laissez une marge autour des personnes et du texte","Lato corto almeno 2.000 px · consigliato 2000×2500 (4:5) · lascia margine attorno a persone e testo","Lado curto com 2.000 px ou mais · 2000×2500 (4:5) recomendado · mantenha pessoas e texto longe das bordas","짧은 변 2,000px 이상 · 권장 2000×2500(4:5) 이상 · 인물과 글자가 사진 가장자리에서 떨어진 구도","短辺2,000px以上・2000×2500（4:5）推奨・人物や文字は端から離してください","短边至少 2,000px · 建议 2000×2500 (4:5) · 人物和文字远离边缘","短邊至少 2,000px・建議 2000×2500（4:5）・人物與文字遠離邊緣","Cạnh ngắn từ 2.000px · khuyên dùng 2000×2500 (4:5) · giữ người và chữ cách xa mép"],
        ["admin.hero.crop.target.hint"] = ["Targets: desktop 1920×1080 and phone 1080×1920. Extra margin helps one source fit both.","Objetivos: PC 1920×1080 y móvil 1080×1920. Más margen ayuda a adaptar una sola foto.","Cibles : ordinateur 1920×1080 et mobile 1080×1920. Une marge généreuse facilite l’adaptation.","Obiettivi: desktop 1920×1080 e mobile 1080×1920. Più margine facilita l’adattamento.","Alvos: computador 1920×1080 e celular 1080×1920. Mais margem ajuda a adaptar uma única foto.","PC 목표 1920×1080 · 폰 목표 1080×1920. 한 장을 함께 쓰므로 원본에 여백이 많을수록 두 화면 모두 자연스럽습니다.","PCは1920×1080、スマホは1080×1920が目安です。余白が多いほど両方に自然に合います。","目标：电脑 1920×1080、手机 1080×1920。保留更多边距可适配两种屏幕。","目標：電腦 1920×1080、手機 1080×1920。保留更多邊距可適配兩種螢幕。","Mục tiêu: máy tính 1920×1080, điện thoại 1080×1920. Nhiều khoảng trống giúp một ảnh hợp cả hai."],
        ["admin.hero.crop.fit"] = ["Show the full photo and allow empty margins","Mostrar toda la foto y permitir márgenes","Afficher toute la photo avec des marges","Mostra tutta la foto consentendo margini","Mostrar a foto inteira e permitir margens","사진을 자르지 않고 여백 허용","写真を切らず余白を許可","显示完整图片并允许留白","顯示完整圖片並允許留白","Hiện toàn bộ ảnh và cho phép khoảng trống"],
        ["admin.hero.crop.fill"] = ["Fill the screen with the selected area","Llenar la pantalla con el área seleccionada","Remplir l’écran avec la zone sélectionnée","Riempi lo schermo con l’area selezionata","Preencher a tela com a área selecionada","선택 영역으로 화면을 빈틈없이 채움","選択範囲で画面全体を埋める","用所选区域填满屏幕","以所選區域填滿螢幕","Lấp đầy màn hình bằng vùng đã chọn"],
        ["admin.hero.crop.full.hint"] = ["The whole image is shown. Different screen ratios may add top/bottom or side margins.","Se muestra toda la imagen. Otras proporciones pueden añadir márgenes.","Toute l’image est affichée. Des marges peuvent apparaître selon le format.","Viene mostrata tutta l’immagine. Rapporti diversi possono aggiungere margini.","A imagem inteira é exibida. Proporções diferentes podem criar margens.","전체 이미지가 표시됩니다. 화면 비율이 다르면 위·아래 또는 좌·우에 여백이 생길 수 있습니다.","画像全体を表示します。画面比率によって上下または左右に余白が生じます。","显示完整图片。屏幕比例不同时可能出现上下或左右留白。","顯示完整圖片。螢幕比例不同時可能出現上下或左右留白。","Hiện toàn bộ ảnh. Tỷ lệ màn hình khác có thể tạo khoảng trống trên/dưới hoặc hai bên."],
        ["admin.hero.crop.drag.hint"] = ["Drag empty space to draw a frame, drag inside to move it, and use the corners to resize. The ratio stays fixed.","Arrastra el espacio vacío para dibujar, el interior para mover y las esquinas para cambiar el tamaño.","Faites glisser le vide pour dessiner, l’intérieur pour déplacer et les coins pour redimensionner.","Trascina lo spazio vuoto per disegnare, l’interno per spostare e gli angoli per ridimensionare.","Arraste o espaço vazio para desenhar, o interior para mover e os cantos para redimensionar.","빈 곳을 끌어 새 사각형을 그리고, 사각형 안쪽은 이동, 네 모서리는 크기 조절입니다. 화면 비율은 자동으로 유지됩니다.","空白をドラッグして枠を描き、内側で移動、四隅でサイズ変更します。比率は固定されます。","拖动空白处绘制区域，拖动内部移动，拖动四角调整大小，比例保持不变。","拖曳空白處繪製區域，拖曳內部移動，拖曳四角調整大小，比例保持不變。","Kéo vùng trống để vẽ khung, kéo bên trong để di chuyển và kéo góc để đổi kích thước; tỷ lệ luôn cố định."],
        ["admin.hero.crop.apply"] = ["Apply and preview","Aplicar y previsualizar","Appliquer et prévisualiser","Applica e visualizza","Aplicar e visualizar","적용하고 미리보기","適用してプレビュー","应用并预览","套用並預覽","Áp dụng và xem trước"],
        ["admin.hero.position"] = ["Hero text position","Posición del texto principal","Position du texte principal","Posizione testo principale","Posição do texto principal","히어로 문구 위치","ヒーローテキスト位置","主视觉文字位置","主視覺文字位置","Vị trí chữ trên ảnh chính"],
        ["admin.hero.position.hint"] = ["Select the desktop or phone preview, then drag the text box. Each position is saved separately.","Selecciona la vista de PC o móvil y arrastra el cuadro de texto. Cada posición se guarda por separado.","Choisissez l’aperçu ordinateur ou mobile puis déplacez le texte. Chaque position est enregistrée séparément.","Seleziona l’anteprima desktop o mobile e trascina il testo. Le posizioni vengono salvate separatamente.","Selecione a prévia de computador ou celular e arraste o texto. Cada posição é salva separadamente.","PC 또는 폰 미리보기를 먼저 선택한 뒤 문구 박스를 끌어 주세요. 두 위치는 따로 저장되며 드래그를 놓으면 즉시 반영됩니다.","PCまたはスマホのプレビューを選び、テキスト枠をドラッグしてください。位置は別々に保存されます。","先选择电脑或手机预览，再拖动文字框。两个位置将分别保存。","先選擇電腦或手機預覽，再拖曳文字框。兩個位置將分別儲存。","Chọn bản xem trước máy tính hoặc điện thoại rồi kéo hộp chữ. Mỗi vị trí được lưu riêng."],
        ["admin.hero.position.top"] = ["Top text","Texto superior","Texte supérieur","Testo superiore","Texto superior","상단 문구","テキスト上部","顶部文字","頂部文字","Chữ phía trên"],
        ["admin.hero.position.bottom"] = ["Venue and guestbook","Lugar y libro de visitas","Lieu et livre d’or","Sede e messaggi","Local e mensagens","하단 장소·방명록","会場・ゲストブック","场地和留言簿","場地與留言簿","Địa điểm và sổ lưu bút"],
        ["admin.hero.position.drag"] = ["Drag to adjust","Arrastrar para ajustar","Faire glisser pour ajuster","Trascina per regolare","Arraste para ajustar","끌어서 조정","ドラッグして調整","拖动调整","拖曳調整","Kéo để chỉnh"],
        ["admin.story.hint"] = ["Choose the Story layout to manage chapter text and cover photos.","Elige el diseño Historia para gestionar textos y portadas.","Choisissez la mise en page Histoire pour gérer les textes et photos.","Scegli il layout Storia per gestire testi e foto di copertina.","Escolha o layout História para gerenciar textos e fotos.","Story 레이아웃을 선택하면 챕터 문구와 대표 사진을 관리할 수 있습니다.","Storyレイアウトで章の文章と代表写真を管理できます。","选择故事布局后可管理章节文字和封面图片。","選擇故事版面後可管理章節文字與封面圖片。","Chọn bố cục Câu chuyện để quản lý nội dung và ảnh đại diện từng chương."],
        ["admin.story.detail.hint"] = ["The four default chapters stay in place; add more chapters when needed.","Los cuatro capítulos predeterminados se conservan; añade más cuando sea necesario.","Les quatre chapitres par défaut sont conservés ; ajoutez-en si nécessaire.","I quattro capitoli predefiniti restano; aggiungine altri se necessario.","Os quatro capítulos padrão permanecem; adicione mais se necessário.","기본 4개 챕터는 유지되고 필요한 챕터를 추가할 수 있습니다.","標準の4章は維持され、必要に応じて追加できます。","保留四个默认章节，可按需添加更多章节。","保留四個預設章節，可依需要新增更多章節。","Bốn chương mặc định được giữ lại; có thể thêm chương khi cần."],
        ["admin.story.add"] = ["Add chapter","Añadir capítulo","Ajouter un chapitre","Aggiungi capitolo","Adicionar capítulo","챕터 추가","章を追加","添加章节","新增章節","Thêm chương"],
        ["admin.story.save"] = ["Save chapter","Guardar capítulo","Enregistrer le chapitre","Salva capitolo","Salvar capítulo","챕터 저장","章を保存","保存章节","儲存章節","Lưu chương"],
        ["admin.story.title"] = ["Chapter title","Título del capítulo","Titre du chapitre","Titolo capitolo","Título do capítulo","챕터 제목","章タイトル","章节标题","章節標題","Tiêu đề chương"],
        ["admin.story.body"] = ["Chapter text","Texto del capítulo","Texte du chapitre","Testo capitolo","Texto do capítulo","챕터 본문","章本文","章节正文","章節內文","Nội dung chương"],
        ["admin.story.photo"] = ["Cover photo","Foto de portada","Photo de couverture","Foto di copertina","Foto de capa","대표 사진","代表写真","封面图片","封面圖片","Ảnh đại diện"],
        ["admin.story.photo.auto"] = ["Choose automatically","Elegir automáticamente","Choisir automatiquement","Scegli automaticamente","Escolher automaticamente","자동 선택","自動選択","自动选择","自動選擇","Chọn tự động"],
        ["admin.photobook.hint"] = ["Choose the Photo Book layout to manage album pages.","Elige el diseño Álbum para gestionar sus páginas.","Choisissez la mise en page Livre photo pour gérer les pages.","Scegli il layout Fotolibro per gestire le pagine.","Escolha o layout Livro de fotos para gerenciar páginas.","PhotoBook 레이아웃을 선택하면 앨범 페이지별 사진과 문구를 관리할 수 있습니다.","PhotoBookレイアウトでアルバムページを管理できます。","选择相册布局后可管理相册页面。","選擇相片書版面後可管理相簿頁面。","Chọn bố cục Sách ảnh để quản lý từng trang album."],
        ["admin.photobook.detail.hint"] = ["Pages appear prominently at the top. Missing photos are filled from the gallery; the four defaults remain.","Las páginas aparecen arriba. Las fotos vacías se completan desde la galería y se conservan las cuatro predeterminadas.","Les pages sont mises en avant. Les photos manquantes proviennent de la galerie et les quatre pages par défaut restent.","Le pagine appaiono in alto. Le foto mancanti sono prese dalla galleria e le quattro predefinite restano.","As páginas aparecem em destaque. Fotos ausentes vêm da galeria e as quatro padrão permanecem.","포토북 상단에 크게 표시되며 사진이 없으면 갤러리 순서대로 자동 보충됩니다. 기본 4개는 유지됩니다.","上部に大きく表示され、写真未指定時はギャラリー順で補完されます。標準4ページは維持されます。","页面会突出显示在顶部，缺少图片时按相册顺序自动补充，并保留四个默认页面。","頁面會突出顯示於頂部，缺少圖片時依相簿順序自動補充，並保留四個預設頁面。","Trang hiển thị nổi bật phía trên; ảnh thiếu được bổ sung từ thư viện và giữ bốn trang mặc định."],
