        ["admin.design.custom.theme.hint"] = ["Saved separately from the layout, so colors remain when versions change.","Se guarda aparte del diseño; los colores permanecen al cambiar de versión.","Enregistré séparément ; les couleurs restent lors d’un changement de version.","Salvato separatamente; i colori restano cambiando versione.","Salvo separadamente; as cores permanecem ao mudar a versão.","레이아웃과 별도로 저장되어 버전이 바뀌어도 색상이 유지됩니다.","レイアウトとは別に保存され、バージョン変更後も色が維持されます。","与布局分开保存，更换版本后颜色仍会保留。","與版面分開儲存，更換版本後色彩仍會保留。","Được lưu riêng nên màu vẫn giữ khi đổi phiên bản."],
        ["admin.design.theme.name"] = ["Theme name","Nombre del tema","Nom du thème","Nome tema","Nome do tema","테마 이름","テーマ名","主题名称","主題名稱","Tên giao diện"],
        ["admin.design.auto.palette"] = ["Auto-match from primary color","Ajustar desde el color principal","Harmoniser depuis la couleur principale","Adatta dal colore principale","Ajustar pela cor principal","대표 색상으로 자동 맞춤","代表色から自動調整","根据主色自动匹配","依主色自動搭配","Tự phối theo màu chính"],
        ["admin.design.palette.rebuild"] = ["Rebuild automatic palette","Regenerar paleta automática","Régénérer la palette automatique","Rigenera palette automatica","Refazer paleta automática","자동 팔레트 다시 만들기","自動パレットを再生成","重新生成自动配色","重新產生自動配色","Tạo lại bảng màu tự động"],
        ["admin.design.custom.use"] = ["Use custom theme","Usar tema personalizado","Utiliser le thème personnalisé","Usa tema personalizzato","Usar tema personalizado","나만의 테마 사용","カスタムテーマを使用","使用自定义主题","使用自訂主題","Dùng giao diện tùy chỉnh"],
        ["admin.design.custom.selected"] = ["Custom theme selected","Tema personalizado seleccionado","Thème personnalisé sélectionné","Tema personalizzato selezionato","Tema personalizado selecionado","나만의 테마 선택됨","カスタムテーマ選択済み","已选择自定义主题","已選擇自訂主題","Đã chọn giao diện tùy chỉnh"],
        ["admin.design.version.notice"] = ["This invitation keeps v{0}. Active v{1} is available; select it above to update.","Esta invitación mantiene v{0}. La v{1} está disponible; selecciónala arriba para actualizar.","Cette invitation conserve v{0}. La v{1} est disponible ; sélectionnez-la ci-dessus.","Questo invito mantiene v{0}. È disponibile v{1}; selezionala sopra.","Este convite mantém v{0}. A v{1} está disponível; selecione-a acima.","현재 청첩장은 v{0}을 유지합니다. 활성 v{1}로 업데이트하려면 위에서 선택하세요.","この招待状はv{0}を維持しています。有効なv{1}へ更新するには上で選択してください。","此请柬仍使用 v{0}。可用活动版本 v{1}，请在上方选择更新。","此喜帖仍使用 v{0}。可用的啟用版本為 v{1}，請於上方選擇更新。","Thiệp này vẫn dùng v{0}. Bản v{1} đang hoạt động; chọn ở trên để cập nhật."],
        ["admin.design.follow.active"] = ["Automatically follow the active version","Seguir automáticamente la versión activa","Suivre automatiquement la version active","Segui automaticamente la versione attiva","Seguir automaticamente a versão ativa","새 활성 버전 자동 적용","有効バージョンを自動適用","自动跟随活动版本","自動跟隨啟用版本","Tự động theo phiên bản hoạt động"],
        ["admin.design.follow.active.hint"] = ["Pinned to v{0} by default. Enable this only to follow future approvals and rollbacks.","Se fija en v{0}. Actívalo solo para seguir aprobaciones y reversiones futuras.","Épinglé à v{0}. Activez uniquement pour suivre les futures versions et restaurations.","Bloccato su v{0}. Attiva solo per seguire approvazioni e rollback futuri.","Fixado em v{0}. Ative apenas para seguir aprovações e reversões futuras.","기본은 v{0}에 고정됩니다. 이후 승인 버전과 롤백을 자동 반영할 때만 켜세요.","通常はv{0}に固定されます。今後の承認版とロールバックを追従する場合のみ有効にしてください。","默认固定到 v{0}。仅在需要跟随后续批准版本和回滚时启用。","預設固定於 v{0}。僅在需要跟隨後續核准版本與回復時啟用。","Mặc định ghim ở v{0}. Chỉ bật để theo các bản duyệt và hoàn tác sau này."],
        ["admin.design.apply.pin.hint"] = ["Applying pins this invitation to v{0}. Automatic version following can be enabled afterward.","Al aplicar, la invitación se fija en v{0}. El seguimiento automático puede activarse después.","L’application épingle l’invitation à v{0}. Le suivi automatique peut être activé ensuite.","L’applicazione blocca l’invito su v{0}. Il seguito automatico può essere attivato dopo.","A aplicação fixa o convite em v{0}. O acompanhamento automático pode ser ativado depois.","적용하면 v{0}에 고정됩니다. 자동 버전 추적은 적용 후 켤 수 있습니다.","適用するとv{0}に固定されます。自動追従は適用後に有効にできます。","应用后将固定到 v{0}。之后可启用自动版本跟随。","套用後將固定於 v{0}。之後可啟用自動版本跟隨。","Khi áp dụng, thiệp được ghim ở v{0}. Có thể bật theo dõi tự động sau đó."],
        ["admin.design.renderer.missing"] = ["The screen renderer for this layout is not ready yet.","El renderizador de este diseño aún no está listo.","Le moteur d’affichage de cette mise en page n’est pas encore prêt.","Il renderer di questo layout non è ancora pronto.","O renderizador deste layout ainda não está pronto.","이 레이아웃의 화면 렌더러가 아직 준비되지 않았습니다.","このレイアウトの画面レンダラーはまだ準備中です。","此布局的页面渲染器尚未就绪。","此版面的畫面渲染器尚未就緒。","Trình hiển thị của bố cục này chưa sẵn sàng."],
        ["admin.design.premium.required"] = ["Enable Premium to use all Premium layouts.","Activa Premium para usar todos los diseños Premium.","Activez Premium pour utiliser toutes les mises en page Premium.","Attiva Premium per usare tutti i layout Premium.","Ative o Premium para usar todos os layouts Premium.","Premium을 활성화하면 모든 Premium 레이아웃을 사용할 수 있습니다.","Premiumを有効にするとすべてのPremiumレイアウトを利用できます。","启用 Premium 即可使用所有 Premium 布局。","啟用 Premium 即可使用所有 Premium 版面。","Bật Premium để dùng mọi bố cục Premium."],
        ["admin.design.section.hide.title"] = ["Hide this section from the invitation","Ocultar esta sección de la invitación","Masquer cette section de l’invitation","Nascondi questa sezione dall’invito","Ocultar esta seção do convite","이 섹션을 청첩장에서 숨깁니다","招待状からこのセクションを非表示","从请柬中隐藏此区块","從喜帖隱藏此區段","Ẩn mục này khỏi thiệp"],
        ["admin.design.section.show.title"] = ["Show this section on the invitation","Mostrar esta sección en la invitación","Afficher cette section sur l’invitation","Mostra questa sezione nell’invito","Mostrar esta seção no convite","이 섹션을 청첩장에 다시 표시합니다","招待状にこのセクションを再表示","在请柬中重新显示此区块","在喜帖重新顯示此區段","Hiện lại mục này trên thiệp"],
        ["admin.design.auto.palette.hint"] = ["Choose one primary color and readable background, text, button and border colors are generated automatically. You can fine-tune them below.","Elige un color principal y se generan colores legibles. Puedes ajustarlos abajo.","Choisissez une couleur principale ; des couleurs lisibles sont générées. Ajustez-les ci-dessous.","Scegli un colore principale: gli altri colori leggibili vengono generati. Puoi regolarli sotto.","Escolha uma cor principal e as demais cores legíveis serão geradas. Ajuste abaixo.","대표 색상 하나를 고르면 읽기 편한 배경·본문·버튼·경계선을 자동 생성합니다. 아래에서 다시 조정할 수 있습니다.","代表色を選ぶと読みやすい背景・本文・ボタン・境界色を自動生成します。下で微調整できます。","选择一个主色后会自动生成易读的背景、文字、按钮和边框颜色，可在下方微调。","選擇一個主色後會自動產生易讀的背景、文字、按鈕與邊框色，可於下方微調。","Chọn một màu chính để tự tạo nền, chữ, nút và viền dễ đọc; có thể chỉnh bên dưới."],
